import type { SVGProps } from "react";

/**
 * BVK's own icon set, supplied as SVG artwork and inlined here so each icon
 * takes its colour from the page (currentColor) like the lucide icons it sits
 * beside. The markup is the artwork's paths only; see content/pages for use.
 */

type IconProps = SVGProps<SVGSVGElement> & { size?: number };

function make(viewBox: string, inner: string) {
  const Icon = ({ size, className, ...rest }: IconProps) => (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={viewBox}
      fill="currentColor"
      width={size}
      height={size}
      className={className}
      aria-hidden
      focusable="false"
      {...rest}
      dangerouslySetInnerHTML={{ __html: inner }}
    />
  );
  return Icon;
}

